# Niveau HSK 6 (chinois, HSK 2.0 niveau 6) : 8 étapes sur la route de la soie, leçons et examen blanc (français + anglais).
# Mode histoire : interprète de Zhang Qian, envoyé par l'empereur Wu des Han vers les royaumes de l'Ouest (voir gen-story.py).
# Écrit aussi la section HSK 6 de l'onglet Hanzi.
# Usage : python3 scripts/hsk6-level.py   (après les niveaux HSK 1 à 5)
from zh_common import *

# Slugs déjà pris par un autre niveau : suffixe « -h6 » (le même mot peut exister en japonais, coréen…).
_TAKEN = set()
for _p in ALL_LEVELS + HSK_PATHS[:5]:
    for _it in items_of(json.load(open(os.path.join(ROOT, _p), encoding='utf-8'))):
        _TAKEN.add(_it['slug'])
for _th in json.load(open(os.path.join(ROOT, 'content/expressions/expressions.json'), encoding='utf-8'))['themes']:
    _TAKEN.update(_e['slug'] for _e in _th['expressions'])
def _free(full):
    return full + '-h6' if full in _TAKEN else full
_Z, _ZG, _H = Z, ZG, H
def Z(slug, *a): return {**_Z(slug, *a), 'slug': _free('zh-' + slug)}
def ZG(slug, *a): return {**_ZG(slug, *a), 'slug': _free('gram-zh-' + slug)}
def H(slug, *a): return {**_H(slug, *a), 'slug': _free('hz-' + slug)}


