        FB(COMPLETE, '我本来想出去散步，＿下起了大雨。', ['不料', '一向', '乃至'], '不料', ('Contre toute attente : 不料.', 'Unexpectedly: 不料.'), ('Je voulais aller me promener, mais il s’est mis à pleuvoir à verse.', 'I meant to go for a walk, but it suddenly started pouring.')),
        FB(COMPLETE, '警察把小偷＿了起来，他跑不掉了。', ['包围', '释放', '投降'], '包围', ('Encercler : 包围.', 'Surround: 包围.'), ('La police a encerclé le voleur : il ne peut plus s’enfuir.', 'The police surrounded the thief: he can’t get away now.')),
        DC(ANSWER, [('匈奴首领', '你投降吧，我可以放你回去。')], ('Le chef xiongnu te propose de te rendre (tu refuses fièrement).', 'The Xiongnu chief offers to let you go if you surrender (you proudly refuse).'), ['我是汉朝的使者，绝不投降。', '我已经逃脱了看守。', '冲突非常英勇。'], '我是汉朝的使者，绝不投降。', ('Refuser de se rendre : 绝不投降.', 'Refuse to surrender: 绝不投降.')),
        TF('那些俘虏后来都被释放了。', ('Les prisonniers ont été exécutés.', 'The prisoners were executed.'), FAUX, ('被释放 = être libéré.', '被释放 = to be released.')),
