        FB(COMPLETE, '为这么小的事生气，你＿太小气了吧。', ['未免', '不免', '一向'], '未免', ('Un peu trop : 未免太….', 'Rather too: 未免太….'), ('Te fâcher pour si peu, c’est quand même un peu mesquin.', 'Getting angry over something so small is rather petty.')),
        DC(ANSWER, [('朋友', '听说你的孩子考上了大学，你一定很欣慰吧？')], ('Un ami pense que tu es réconforté par la réussite de ton enfant (oui, tous ces efforts ont payé).', 'A friend thinks you are gratified by your child’s success (yes, all the effort paid off).'), ['是啊，这么多年的努力没有白费。', '我非常恐惧奶酪。', '惭愧是一种习俗。'], '是啊，这么多年的努力没有白费。', ('Pas en vain : 没有白费.', 'Not in vain: 没有白费.')),
        TF('考试没考好，他感到很沮丧。', ('Il est ravi de son examen.', 'He is delighted with his exam.'), FAUX, ('沮丧 = abattu.', '沮丧 = dejected.')),
