        FB(COMPLETE, '他把真实的情况＿了起来，谁也没告诉。', ['隐瞒', '暴露', '察觉'], '隐瞒', ('Dissimuler : 隐瞒.', 'Conceal: 隐瞒.'), ('Il a caché la vérité et n’en a parlé à personne.', 'He concealed the truth and told nobody.')),
        DC(ANSWER, [('甘父', '今晚月亮太亮了，我们还走吗？')], ('Ganfu s’inquiète de la pleine lune (attendre un meilleur moment).', 'Ganfu worries about the bright moon (wait for a better moment).'), ['时机还不成熟，再等几天吧。', '我们已经冒充了奶酪。', '警惕是一种逃亡。'], '时机还不成熟，再等几天吧。', ('Le moment n’est pas mûr : 时机不成熟.', 'The time isn’t ripe: 时机不成熟.')),
        TF('他冒充警察骗了很多人的钱。', ('Il se faisait passer pour un policier.', 'He passed himself off as a police officer.'), VRAI, ('冒充警察 = se faire passer pour un policier.', '冒充警察 = pose as a police officer.')),
