        Z('huilü', '汇率', 'huìlǜ', ('taux de change', 'exchange rate')),
        Z('fanrong', '繁荣', 'fánróng', ('prospère ; prospérité', 'prosperous; prosperity')),
        Z('shuaitui', '衰退', 'shuāituì', ('récession ; décliner', 'recession; to decline')),
