        Z('tonghuopengzhang', '通货膨胀', 'tōnghuò péngzhàng', ('inflation', 'inflation')),
        Z('xiaofei', '消费', 'xiāofèi', ('consommer ; consommation', 'to consume; consumption')),
        Z('chuxu', '储蓄', 'chǔxù', ('épargne ; épargner', 'savings; to save')),
        Z('lixi', '利息', 'lìxī', ('intérêts (financiers)', 'interest (money)')),
