        Z('shijie', '使节', 'shǐjié', ('diplomate, envoyé officiel', 'diplomatic envoy')),
        Z('guoshu', '国书', 'guóshū', ('lettres de créance', 'letter of credence')),
        Z('lianmeng', '联盟', 'liánméng', ('alliance', 'alliance')),
        Z('jiemeng', '结盟', 'jiéméng', ('s’allier', 'to form an alliance')),
        Z('mengyou', '盟友', 'méngyǒu', ('allié', 'ally')),
