        FB(COMPLETE, '对表现突出的员工，公司将＿奖励。', ['予以', '加以', '莫非'], '予以', ('Accorder : 予以奖励.', 'Grant: 予以奖励.'), ('L’entreprise récompensera les employés les plus remarquables.', 'The company will reward outstanding employees.')),
        DC(ANSWER, [('大臣', '如果我们和汉朝结盟，匈奴会不会报复？')], ('Un ministre yuezhi craint les représailles (unis, nous serons plus forts).', 'A Yuezhi minister fears revenge (united, we will be stronger).'), ['只要我们联合起来，匈奴就不敢来。', '国书是一种中立。', '我们调解了骆驼。'], '只要我们联合起来，匈奴就不敢来。', ('S’unir : 联合起来.', 'Unite: 联合起来.')),
